            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0,0,0,0.7);
            display: none;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            color: white;
            z-index: 20;
        }
    </style>
</head>
<body>

<div id="container">
    <h2>AI时代的隐私保险箱</h2>
    <svg id="svg-canvas" viewBox="0 0 800 400">
        <!-- 保险箱 -->
        <rect x="300" y="100" width="200" height="200" fill="#bdc3c7" stroke="#7f8c8d" stroke-width="5" rx="10"/>
        <circle cx="400" cy="200" r="30" fill="#7f8c8d"/>
        <text x="350" y="280" font-size="18" fill="#2c3e50">隐私保险箱</text>

        <!-- 数据卡片组 -->
        <g id="cards" cursor="grab">
            <rect id="card-face" x="50" y="50" width="100" height="40" fill="#3498db" rx="5"/>
            <text x="75" y="75" fill="white">人脸</text>

            <rect id="card-voice" x="50" y="120" width="100" height="40" fill="#3498db" rx="5"/>
            <text x="75" y="145" fill="white">声音</text>

            <rect id="card-hobby" x="650" y="50" width="100" height="40" fill="#9b59b6" rx="5"/>
            <text x="665" y="75" fill="white">日常喜好</text>

            <rect id="card-addr" x="650" y="120" width="100" height="40" fill="#9b59b6" rx="5"/>
            <text x="665" y="145" fill="white">家庭地址</text>
        </g>
    </svg>

    <div class="controls">
        <button id="btn-agreement">查看协议陷阱</button>
    </div>

    <div id="risk-box">
        <h4 style="color:#ff4d4f">⚠️ 风险警告</h4>
