            border-radius: 8px;
            transition: transform 0.2s;
        }
        #btn-polite { background-color: #4CAF50; color: white; }
        #btn-rude { background-color: #f44336; color: white; }
        button:hover { transform: scale(1.05); }
        .label { position: absolute; font-weight: bold; color: #333; }
    </style>
</head>
<body>

    <div id="canvas-container">
        <canvas id="interactionCanvas"></canvas>
    </div>

    <div class="controls">
        <button id="btn-polite">发送文明语言</button>
        <button id="btn-rude">发送不文明语言</button>
    </div>

    <script>
        const canvas = document.getElementById('interactionCanvas');
        const ctx = canvas.getContext('2d');
        let civility = 100;
        let aiCorruption = 0;
        let particles = [];

        function resize() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        window.addEventListener('resize', resize);
        resize();

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // 绘制用户
            ctx.fillStyle = `rgb(${255 - civility}, 100, 100)`;
            ctx.fillRect(50, 150, 100, 150);
            ctx.fillText("用户", 85, 320);

            // 绘制AI
            ctx.fillStyle = `rgb(${100 + aiCorruption}, ${100 + aiCorruption}, ${200 - aiCorruption})`;
            ctx.fillRect(canvas.width - 150, 150, 100, 150);
            ctx.fillText("AI 机器人", canvas.width - 140, 320);

            // 绘制文明度进度条
            ctx.fillStyle = "#ddd";
            ctx.fillRect(50, 50, 100, 20);
            ctx.fillStyle = "#4CAF50";
            ctx.fillRect(50, 50, civility, 20);
            ctx.fillText("现实文明度", 50, 40);

            // 粒子动画
            particles.forEach((p, index) => {
                p.x += p.vx;
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
                ctx.fill();
                if (p.x > canvas.width - 150 || p.x < 150) particles.splice(index, 1);
            });

            requestAnimationFrame(draw);
        }

        function sendData(type) {
            if (type === 'rude') {
                civility = Math.max(0, civility - 10);
                aiCorruption = Math.min(150, aiCorruption + 20);
                particles.push({x: 150, y: 200, vx: 5, color: 'red'});
            } else {
                civility = Math.min(100, civility + 5);
                aiCorruption = Math.max(0, aiCorruption - 10);
                particles.push({x: 150, y: 200, vx: 5, color: 'green'});
            }
        }

        document.getElementById('btn-polite').addEventListener('click', () => sendData('polite'));
        document.getElementById('btn-rude').addEventListener('click', () => sendData('rude'));

        draw();
    </script>
</body>
</html>", "visual_aid_urls": [], "priority": 0.75}, {"id": "M4", "content": "大家看大屏幕上的这两张图，左边是AI生成的‘外星人袭击某地’的新闻图片，看起来极其逼真；右边则是官方的辟谣和细节放大图。如果你在网上刷到左边这张图，你会怎么去拆穿这个AI制造的‘逼真谎言’，找出它的破绽呢？", "question_type": "main", "lesson_presentation_script": "当我们学会用文明的态度与AI交流后，我们会发现它简直是个‘万事通’，不仅说话客气，给出的解答也头头是道，甚至还能画出像左边这样毫无破绽的图片。这时候，很多同学就会产生一种‘AI崇拜’，觉得‘既然是AI写的、AI画的，那肯定就是真的’。但实际上，AI有一个致命的毛病叫‘幻觉’，它会一本正经地胡说八道，甚至被坏人用来制造谣言。那么，在这个‘真假难辨’的AI时代，我们该怎么做，才不会被它牵着鼻子走？请大家仔细观察右边的对比图，尤其是那些被圈出来的细节，比如外星人多出来的手指、背景里扭曲的线条，想一想，我们要通过哪些具体的步骤和方法，才能当好一个合格的‘信息侦探’？", "explanation": "【参考答案】辨析AI内容真伪的“三步法”：1. 观察微观细节（寻找AI绘画的常见破绽，如不合常理的手指数量、扭曲的光影、奇怪的背景文字、不自然的皮肤纹理等）；2. 查验权威来源（通过官方媒体、政府网站、专业辟谣平台核实该信息是否属实）；3. 对比多方信息（使用搜索引擎进行图片反向搜索或多源对比，不轻信单一信源）。
【解题思路】引导学生从微观（画面细节、逻辑漏洞）和宏观（多源验证、权威核实）两个层面建立批判性思维，掌握识破AI虚假信息的操作步骤。
【易错点】学生往往因为AI生成的文字通顺、图片精美就默认其是真实的，缺乏“AI会犯错、会无中生有”的批判性防范意识。", "knowledge_points": ["KP3"], "cognitive_level": "分析", "difficulty": 0.7, "design_intent": "培养学生的批判性信息素养，打破对AI的盲目迷信，攻克易错点（误认为AI生成绝对真实）。", "design_rationale": "", "visual_aid_prompt": "设计一个交互式‘AI真伪放大镜’HTML/SVG页面。页面左侧展示一张AI合成的‘外星人降临学校操场’的精美图片。学生可以拖动右侧的‘侦探放大镜’在图片上移动。当放大镜移到特定区域（如外星人的手部有6根手指、教学楼窗户线条扭曲、背景横幅上的文字是乱码）时，该区域会自动放大，并弹出细节解析。右边面板提供‘核实工具箱’，学生可点击‘搜索权威媒体’、‘图片反向搜索’按钮，模拟获取真实的辟谣信息，最终拼凑出完整的‘辟谣报告’。", "visual_aid_type": "illustration", "visual_aid_html": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'; media-src 'none'; object-src 'none'">
    <meta charset="UTF-8">
    <title>AI真伪侦探：识破虚假新闻</title>
    <style>
        :root { --primary: #2563eb; --bg: #f8fafc; }
        body { font-family: sans-serif; background: var(--bg); margin: 0; display: flex; flex-direction: column; align-items: center; height: 100vh; overflow: hidden; }
        #container { width: 800px; height: 600px; background: white; border: 2px solid #ddd; position: relative; display: flex; overflow: hidden; }

        /* 左侧画布区 */
        #canvas-area { width: 500px; height: 600px; position: relative; cursor: crosshair; background: #eee; }
