        /* 放大镜 */
        #magnifier { width: 120px; height: 120px; border: 4px solid #fff; border-radius: 50%; position: absolute; pointer-events: none; box-shadow: 0 0 20px rgba(0,0,0,0.5); background: radial-gradient(circle, transparent 50%, rgba(0,0,0,0.8) 100%); display: none; z-index: 10; }

        /* 右侧工具箱 */
        #toolbox { width: 300px; padding: 20px; border-left: 2px solid #eee; display: flex; flex-direction: column; gap: 15px; }
