        </div>
        <!-- 预设破绽区域 -->
        <div class="clue" style="top: 150px; left: 100px;" data-info="破绽1：外星人的手部有6根手指，这是AI生成常见的解剖学错误。"></div>
        <div class="clue" style="top: 300px; left: 300px;" data-info="破绽2：教学楼窗户线条扭曲，物理结构不符合现实建筑逻辑。"></div>
        <div class="clue" style="top: 80px; left: 250px;" data-info="破绽3：背景横幅上的文字是乱码，AI无法准确生成复杂文字。"></div>
        <div id="magnifier"></div>
    </div>

    <div id="toolbox">
        <h3>🔍 核实工具箱</h3>
        <button id="btn-search">搜索权威媒体</button>
