        <div class="weight" draggable="true" data-val="left" data-type="bad">完全替代手绘</div>
    </div>

    <svg id="balance-svg" viewBox="0 0 800 300">
        <!-- 支架 -->
        <line x1="400" y1="50" x2="400" y2="200" stroke="#555" stroke-width="8" />
        <polygon points="380,250 420,250 400,200" fill="#555" />
        <!-- 横梁 -->
        <line id="beam" x1="200" y1="50" x2="600" y2="50" stroke="#333" stroke-width="6" transform-origin="400 50" />
        <!-- 盘子 -->
        <line x1="200" y1="50" x2="200" y2="150" stroke="#888" stroke-width="3" />
        <line x1="600" y1="50" x2="600" y2="150" stroke="#888" stroke-width="3" />
        <rect id="plate-left" x="150" y="150" width="100" height="20" fill="#ccc" />
        <rect id="plate-right" x="550" y="150" width="100" height="20" fill="#ccc" />
    </svg>

    <div id="status-msg"></div>
</div>

<script>
    const beam = document.getElementById('beam');
    const statusMsg = document.getElementById('status-msg');
    let leftWeight = 0;
    let rightWeight = 0;

    document.querySelectorAll('.weight').forEach(w => {
        w.addEventListener('dragstart', (e) => {
            e.dataTransfer.setData('type', e.target.getAttribute('data-type'));
            e.dataTransfer.setData('val', e.target.getAttribute('data-val'));
            e.dataTransfer.setData('text', e.target.innerText);
        });
    });

    const plates = [document.getElementById('plate-left'), document.getElementById('plate-right')];

    [document.getElementById('plate-left'), document.getElementById('plate-right')].forEach((plate, index) => {
        plate.addEventListener('dragover', e => e.preventDefault());
        plate.addEventListener('drop', e => {
            const type = e.dataTransfer.getData('type');
            const val = e.dataTransfer.getData('val');

            if (index === 0) leftWeight += (type === 'bad' ? 2 : -1);
            else rightWeight += (type === 'bad' ? 2 : -1);

            updateBalance();
        });
    });

    function updateBalance() {
        const tilt = (rightWeight - leftWeight) * 10;
        beam.style.transform = `rotate(${tilt}deg)`;

        if (leftWeight > rightWeight) {
            statusMsg.innerText = "警告：创作行为偏向不诚信，请审视AI使用方式！";
            statusMsg.style.color = "red";
        } else if (rightWeight > leftWeight) {
            statusMsg.innerText = "提示：创作行为符合诚信原则，体现了人机协作！";
            statusMsg.style.color = "green";
        } else {
            statusMsg.innerText = "天平平衡：请继续添加行为砝码进行评估。";
            statusMsg.style.color = "#333";
        }
    }
</script>

</body>
</html>", "visual_aid_urls": [], "priority": 0.92}, {"id": "M6", "content": "快看屏幕上这个让我们纠结的瞬间：已经是晚上十点了，你的作业还没写完，这时候手机里的‘拍照搜题AI’不仅给出了答案，连详细的解题步骤都写好了，只要抄上去就能马上睡觉。面对这样的诱惑，你会怎么选择？为了让我们班以后能更好地使用AI，我们能不能一起制定一份《班级AI自律公约》？", "question_type": "main", "lesson_presentation_script": "同学们，今天我们一起探讨了AI时代的隐私、文明、真伪和公平。道理大家都听懂了，但在现实生活中，我们经常会遇到像屏幕上这样的‘灵魂考验’：是图省事直接抄AI的作业，还是坚持自己思考？是觉得好玩用AI换脸视频去整蛊同学，还是尊重他人的隐私？这些诱惑非常真实，往往就在我们一念之间。我们常说‘知行合一’，知道规则不算本事，能在诱惑面前做出负责任的选择才是真正的智能时代小公民。现在，就请大家结合我们今天学到的四个维度——隐私、文明、真实、公平，以小组为单位，为我们班量身定制一份《班级AI使用自律公约》。每组至少写出两条具体、可操作的规则，让我们一起用规则来保护我们的成长！", "explanation": "【参考答案】1. 面对诱惑的负责任选择：拒绝直接复制AI答案，将其作为思路引导工具，弄懂后自主书写；不制作、不传播可能侵犯他人隐私或丑化他人的AI视频。2. 《班级AI使用自律公约》示例条目：
- 【隐私篇】不随意上传同学的照片和声音进行AI处理，保护个人生物信息。
- 【文明篇】对AI聊天机器人使用礼貌用语，不故意诱导其输出不良言论。
- 【真实篇】对AI提供的信息保持怀疑，至少通过两个渠道核实后再使用或分享。
- 【公平篇】用AI辅助学习或创作时，主动向老师声明，绝不直接复制AI生成内容作为原创。
