        :root { --primary: #2c3e50; --accent: #e74c3c; --highlight: #f1c40f; }
        body { font-family: sans-serif; background: #f4f7f6; color: var(--primary); display: flex; justify-content: center; align-items: center; height: 100vh; margin: 0; overflow: hidden; }
        #app { width: 800px; height: 600px; background: white; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.1); display: flex; padding: 20px; gap: 20px; box-sizing: border-box; }

        .article-panel { flex: 1; border: 2px solid #eee; padding: 15px; border-radius: 8px; overflow-y: auto; }
        .tool-panel { width: 220px; display: flex; flex-direction: column; gap: 15px; }

