        #magnifier { position: absolute; width: 150px; height: 150px; border: 3px solid #333; border-radius: 50%; background: white; pointer-events: none; overflow: hidden; box-shadow: 0 0 15px rgba(0,0,0,0.3); display: flex; align-items: center; justify-content: center; transform: translate(-50%, -50%); }
