    <div class="cards-area" id="cards">
        <div class="card" draggable="true" id="cardA" data-type="helper">小红：让AI列大纲，自己写正文</div>
        <div class="card" draggable="true" id="cardB" data-type="replace">小明：让AI写好全文，自己复制粘贴</div>
    </div>

    <div class="drop-zones">
        <div class="zone" id="zone-helper" data-accept="helper">合理使用<br>(灵感助手)</div>
