    </div>
    <div id="message"></div>
</div>

<script>
    const cards = document.querySelectorAll('.card');
    const zones = document.querySelectorAll('.zone');
    const message = document.getElementById('message');

    cards.forEach(card => {
        card.addEventListener('dragstart', e => {
            e.dataTransfer.setData('text/plain', e.target.id);
        });
    });

    zones.forEach(zone => {
        zone.addEventListener('dragover', e => e.preventDefault());

        zone.addEventListener('dragenter', () => zone.classList.add('hover'));
        zone.addEventListener('dragleave', () => zone.classList.remove('hover'));

        zone.addEventListener('drop', e => {
            e.preventDefault();
            zone.classList.remove('hover');
            const cardId = e.dataTransfer.getData('text/plain');
            const card = document.getElementById(cardId);
            const cardType = card.getAttribute('data-type');
            const zoneType = zone.getAttribute('data-accept');

            if (cardType === zoneType) {
                zone.classList.add('correct');
                message.textContent = "正确！AI应作为你的思维伙伴，而非代笔者。";
                message.style.color = "var(--success)";
                card.style.opacity = "0.5";
                card.setAttribute('draggable', 'false');
            } else {
                zone.classList.add('wrong');
                message.textContent = "再想想，这个行为是否完全由AI完成了创作？";
                message.style.color = "var(--error)";
                setTimeout(() => zone.classList.remove('wrong'), 1000);
            }
        });
    });
</script>

