        const draggedElement = document.getElementById(id);

        if (id === 'opt2') {
            dropZone.classList.add('success');
            placeholder.innerText = draggedElement.innerText;
            msg.innerText = "太棒了！这是一条非常具体、可执行的班级规则，全班签署成功！";
