            dropZone.classList.remove('success');
            placeholder.innerText = "请再试一次，这条规则还可以更具体哦！";
            msg.innerText = "提示：想想看，怎么做才算保护隐私？";
            stamp.style.display = 'none';
        }
    });
</script>

